package com.offertracker.controller;
import com.offertracker.common.ApiResponse;import com.offertracker.common.BusinessException;import com.offertracker.dto.*;import com.offertracker.service.IdentityService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final IdentityService identity;public AuthController(IdentityService i){identity=i;}@PostMapping("/verification-codes")public ApiResponse<Void> code(@Valid @RequestBody SendVerificationCodeRequest r){identity.sendRegistrationCode(r.phone());return ApiResponse.ok(null);}@PostMapping("/register")public ApiResponse<AuthTokenResponse> register(@Valid @RequestBody RegisterRequest r){return ApiResponse.ok(identity.register(r));}@PostMapping("/login")public ApiResponse<AuthTokenResponse> login(@Valid @RequestBody LoginRequest r){return ApiResponse.ok(identity.login(r));}@PostMapping("/logout")public ApiResponse<Void> logout(@Valid @RequestBody RefreshTokenRequest r){identity.logout(r);return ApiResponse.ok(null);}}
